	borderStyle: 'solid',
	borderColor: {
		'default': 'var(--rcx-input-colors-border-color, var(--rcx-color-stroke-light, #cbced1))',
		'hover': 'var(--rcx-input-colors-hover-border-color, var(--rcx-color-stroke-dark, #6c737a))',
		'focus-within': 'var(--rcx-input-colors-focus-border-color, var(--rcx-color-stroke-highlight, #156ff5))',
		'press': 'var(--rcx-input-colors-active-border-color, var(--rcx-color-stroke-dark, #6c737a))',
	},
	borderRadius: 'var(--rcx-input-border-radius, var(--rcx-border-radius-medium, 0.25rem))',
