// end of generated

export type InputBoxWrapperProps = {
	small?: boolean;
	textarea?: boolean;
	endAddonFlush?: boolean;
	invisible?: boolean;
	hidden?: boolean;
	/** The state of the input it holds, from the input box's `error` and `disabled`. */
	state: 'default' | 'invalid' | 'disabled' | 'invalid-disabled';
	/** The input box's `className`, which lands here when there is an addon. */
	className?: string;
	children?: ReactNode;
};

const layoutOf = (small?: boolean, textarea?: boolean, flush?: boolean) => {
	if (small) {
		return 'small';
	}
	if (textarea) {
		return flush ? 'textarea-flush' : 'textarea';
	}
	return flush ? 'flush' : 'default';
};

// The wrapper is a label, so a `Label` inside it renders as a span
const InputBoxWrapper = ({ small, textarea, endAddonFlush, invisible, hidden, state, className, children }: InputBoxWrapperProps) => (
	<LabelContext.Provider value={true}>
		<InputBoxWrapperContext.Provider value={true}>
			<InputBoxWrapperFrame
				// oxlint-disable-next-line jsx-a11y/label-has-associated-control -- the label wraps the input frame
				render={<label hidden={hidden} />}
				layout={layoutOf(small, textarea, endAddonFlush)}
				state={state}
				invisible={!!invisible}
				className={cx(
					'rcx-box rcx-box--full rcx-box--animated rcx-label rcx-input-box__wrapper',
					endAddonFlush && 'rcx-input-box__wrapper--end-addon-flush',
					className,
				)}
			>
				{children}
			</InputBoxWrapperFrame>
		</InputBoxWrapperContext.Provider>
	</LabelContext.Provider>
);

export default InputBoxWrapper;
